//! /community/ and its three documents: seeded Omega owns the page structure, the copy, the
//! browser client and its run worker (om/community-page/page.om and client.om, regenerated by
//! om/community-page/check.sh). The backend and the post renderer live in their own units.
use maud::{html, Markup, PreEscaped};

pub const TITLE: &str = "Community: builders of Omega, CUDA++ and open compute | AienOS";
pub const DESCRIPTION: &str = "A chronological timeline for people building with Omega, CUDA++ and open compute. Join by invite, sign in with a passkey, post code that runs in place, follow builders. No ranking, no ads, no trackers, and bots only when a person registers and labels them.";
pub const URL: &str = "https://www.aienos.com/community/";
pub const PAGE: &str = include_str!("../../../../om/community-page/main.html");

pub const POLICY_TITLE: &str = "Community rules | AienOS";
pub const POLICY_DESCRIPTION: &str = "Who can join the community on aienos.com, how invites work as a vouch, what is not allowed, how bots are registered and labelled, how reports work and where the public moderation log lives.";
pub const POLICY_URL: &str = "https://www.aienos.com/community/policy/";
pub const POLICY: &str = include_str!("../../../../om/community-page/policy.html");

pub const TERMS_TITLE: &str = "Community terms of use | AienOS";
pub const TERMS_DESCRIPTION: &str = "The plain terms for the community on aienos.com: who runs it, passkeys and invites, the license you grant for your posts, ending an account, no warranty and where copyright notices go.";
pub const TERMS_URL: &str = "https://www.aienos.com/community/terms/";
pub const TERMS: &str = include_str!("../../../../om/community-page/terms.html");

pub const PRIVACY_TITLE: &str = "Community privacy: what is stored | AienOS";
pub const PRIVACY_DESCRIPTION: &str = "Exactly what the community on aienos.com stores about you, including passkeys and invites, the three cookies it sets, what the logs keep, how long backups last, and how to export or delete everything.";
pub const PRIVACY_URL: &str = "https://www.aienos.com/community/privacy/";
pub const PRIVACY: &str = include_str!("../../../../om/community-page/privacy.html");

pub fn render_community_page() -> Markup { html! { (PreEscaped(PAGE)) } }
pub fn render_policy_page() -> Markup { html! { (PreEscaped(POLICY)) } }
pub fn render_terms_page() -> Markup { html! { (PreEscaped(TERMS)) } }
pub fn render_privacy_page() -> Markup { html! { (PreEscaped(PRIVACY)) } }

#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest, Sha256};

    const JS: &str = include_str!("../../../../public/js/community.js");
    const WORKER: &str = include_str!("../../../../public/js/community-worker.js");
    const CSS: &str = include_str!("../../../../public/assets/community.css");

    #[test]
    fn community_generated_artifacts_match_hashes() {
        for (bytes, receipt) in [
            (PAGE, include_str!("../../../../om/community-page/main.html.sha256")),
            (POLICY, include_str!("../../../../om/community-page/policy.html.sha256")),
            (TERMS, include_str!("../../../../om/community-page/terms.html.sha256")),
            (PRIVACY, include_str!("../../../../om/community-page/privacy.html.sha256")),
            (JS, include_str!("../../../../om/community-page/community.js.sha256")),
            (WORKER, include_str!("../../../../om/community-page/community-worker.js.sha256")),
        ] {
            assert_eq!(format!("{:x}", Sha256::digest(bytes.as_bytes())), receipt.split_whitespace().next().expect("digest"));
        }
    }

    #[test]
    fn community_pages_keep_site_rules() {
        for page in [PAGE, POLICY, TERMS, PRIVACY] {
            assert!(!page.contains("<script"), "no inline script");
            assert!(!page.contains("style=\""), "no inline style");
            for (i, _) in page.match_indices(" on") {
                let rest: String = page[i + 3..].chars().take_while(|c| c.is_ascii_alphabetic()).collect();
                assert!(!page[i + 3 + rest.len()..].starts_with('='), "inline handler on{rest}");
            }
            assert!(!page.contains("http://") && !page.contains("https://"), "no external loads or links in the static pages");
            for word in page.split(|c: char| !c.is_ascii_alphabetic()) {
                assert!(!["we", "us", "our", "ours", "ourselves"].contains(&word.to_ascii_lowercase().as_str()), "plural first person: {word}");
            }
        }
        for text in [PAGE, POLICY, TERMS, PRIVACY, JS, WORKER, CSS] {
            assert!(!text.contains('\u{2014}') && !text.contains('\u{2013}'), "no em or en dash");
            assert!(!text.contains("Allen"), "the visible assistant name is Aien");
        }
        assert!(CSS.contains("prefers-reduced-motion: no-preference"));
        assert!(!CSS.contains("http"), "no external assets");
        assert!(!CSS.contains('#'), "palette tokens only, no hex colors");
        for (i, _) in CSS.match_indices('.') {
            let next = CSS[i + 1..].chars().next().unwrap_or(' ');
            assert!(!next.is_ascii_alphabetic() || CSS[i + 1..].starts_with("cm"), "every class is cm- prefixed (offset {i})");
        }
    }

    #[test]
    fn community_documents_say_what_the_design_requires() {
        for text in ["13 years old", "Illegal content", "Harassment and hate", "Spam and undisclosed automation", "Doxxing", "Impersonation", "Bot, run by @owner", "AI-assisted coding is celebrated here, never shamed", "moderation log", "Report", "vouched for by a person", "passkey", "first 7 days", "Invites are a vouch", "revoke", "invites pause"] {
            assert!(POLICY.contains(text), "policy misses {text}");
        }
        for text in ["Drake Stapleton", "license", "No warranty", "drake@aienos.com", "Notices go to", "designated agent", "pending", "delete your account", "passkey", "invite"] {
            assert!(TERMS.contains(text), "terms miss {text}");
        }
        for text in ["public key", "credential id", "signature counter", "private key never leaves your device", "invited you", "Only if you link GitHub", "GitHub numeric id", "Hashed session tokens", "no trackers", "query string", "short-lived memory", "14 days", "downloads everything", "deletes your account", "cm_s", "cm_wc", "cm_st", "cm_gp"] {
            assert!(PRIVACY.contains(text), "privacy misses {text}");
        }
    }

    #[test]
    fn community_client_keeps_its_safety_boundaries() {
        // Only the renderer's post HTML is assigned with innerHTML, in exactly one place.
        assert_eq!(JS.matches("innerHTML").count(), 1);
        assert!(JS.contains("box.innerHTML = typeof html === 'string' ? html : '';"));
        assert!(!JS.contains("outerHTML") && !JS.contains("insertAdjacentHTML") && !JS.contains("document.write"));
        assert!(!JS.contains("eval(") && !JS.contains("new Function"));
        // The only third-party origin is the GitHub avatar host, loaded without a referrer.
        assert!(JS.contains("const AVATAR = 'https://avatars.githubusercontent.com/';"));
        assert!(JS.contains("img.referrerPolicy = 'no-referrer';") && JS.contains("img.loading = 'lazy';"));
        for (i, _) in JS.match_indices("https://") {
            let rest = &JS[i..];
            assert!(
                rest.starts_with("https://avatars.githubusercontent.com/")
                    || rest.starts_with("https://github.com/aien-dev/omega-projects/tree/main/")
                    || rest.starts_with("https://github.com/' + user.github_login")
                    || rest.starts_with("https://github.com/' + me.github_login"),
                "unexpected origin at {i}"
            );
        }
        // GitHub profile links are built only from a login that passed LOGIN_RE.
        assert!(JS.contains("const LOGIN_RE = /^[A-Za-z0-9-]{1,39}$/;"));
        assert_eq!(JS.matches("LOGIN_RE.test(").count(), 2);
        // Passkeys: WebAuthn ceremonies through the community API only, binary fields as base64url.
        assert!(JS.contains("navigator.credentials.create({ publicKey: creationOptions(opts.data) })"));
        assert!(JS.contains("navigator.credentials.get({ publicKey: requestOptions(result.data) })"));
        for path in ["'/auth/passkey/register/options'", "'/auth/passkey/register/verify'", "'/auth/passkey/login/options'", "'/auth/passkey/login/verify'", "'/me/passkeys/add/options'", "'/me/passkeys/add/verify'", "'/invites/revoke'", "'/invites/revouch'"] {
            assert!(JS.contains(path), "client misses {path}");
        }
        assert!(!JS.contains("auth/login") && !JS.contains("loginUrl"), "the old GitHub-only login path is gone");
        assert!(JS.contains("init.headers['X-CM-CSRF'] = state.csrf;"));
        assert!(JS.contains("const OMEGA = '/aien/api/omega';") && JS.contains("const CALL_MS = 3000;"));
        assert!(JS.contains("new Worker('/js/community-worker.js')") && JS.contains("worker.terminate();"));
        assert!(WORKER.contains("WebAssembly.instantiate(job.module, {})"));
        // The client never inserts live posts on its own: it only shows the N new posts button.
        assert!(JS.contains("ui.fresh.hidden = false;"));
    }

    #[test]
    fn community_is_the_first_secondary_nav_entry() {
        assert_eq!(crate::components::navbar::NAV_SECONDARY[0], ("Community", "/community/"));
    }
}
